"""Read only campaign measurements and write a new, versioned local review report."""
from pathlib import Path
import sqlite3,json,datetime,statistics,hashlib,shutil
ROOT=Path(__file__).resolve().parents[1]
CID='2026-10-12-primary-projects'
NOW=datetime.datetime.now(datetime.timezone.utc)
DEADLINE=datetime.datetime(2026,10,12,17,tzinfo=datetime.timezone.utc)
con=sqlite3.connect('file:'+str(ROOT/'data/factory.sqlite')+'?mode=ro',uri=True)
rows=[json.loads(r[0]) for r in con.execute('SELECT data FROM campaign_slots WHERE campaign_id=?',(CID,))]
state=json.loads(con.execute('SELECT data FROM campaigns WHERE id=?',(CID,)).fetchone()[0])
def date(s):return datetime.datetime.fromisoformat(s.replace('Z','+00:00'))
def completed(row):return row['status'] in ['AWAITING_APPROVAL','APPROVED','REJECTED'] and bool((row.get('validation') or {}).get('passed')) and any(v['stage']==3 and v.get('value') for v in row['versions'])
versions=[v for row in rows for v in row['versions']]
done=[r for r in rows if completed(r)]
latencies={}
for model in ['qwen','bonsai']:
 group=[v for v in versions if v['result']['contract']['model']==model]
 latencies[model]={metric:{'samples':len(values),'meanSeconds':statistics.mean(values)/1000 if values else None} for metric in ['loadMs','inferMs','unloadMs'] for values in [[v['result']['lifecycle'][metric] for v in group if v['result']['lifecycle'].get(metric) is not None]]}
package_minutes=[(max(date(v['result']['completedAt']) for v in r['versions'] if v['result'].get('completedAt'))-min(date(v['result']['createdAt']) for v in r['versions'])).total_seconds()/60 for r in done]
start=min(date(v['result']['createdAt']) for v in versions)
end=max(date(v['result']['completedAt']) for v in versions if v['result'].get('completedAt'))
observed_hours=(end-start).total_seconds()/3600
rate=len(done)/observed_hours if observed_hours else 0
attempted=sum(bool(r['versions']) for r in rows)
remaining=50-len(done)
candidates=[json.loads(p.read_text()) for p in sorted((ROOT/'data/source-recovery/candidates').glob('*.json'))]
counts={p:sum(r['projectId']==p for r in done) for p in ['whodunnit','gigwise','terra-steam-tycoon','angband','find-my-needs']}
report={'campaignId':CID,'capturedAt':NOW.isoformat(),'deadline':DEADLINE.isoformat(),'hoursRemaining':max(0,(DEADLINE-NOW).total_seconds()/3600),'counts':counts,'completedValidated':len(done),'generatedDrafts':sum(bool(r.get('proposal')) for r in rows),'stageVersions':len(versions),'modelLatencies':latencies,'packageRuntime':{'samples':len(package_minutes),'minutes':package_minutes,'meanMinutes':statistics.mean(package_minutes) if package_minutes else None},'observation':{'start':start.isoformat(),'end':end.isoformat(),'elapsedHours':observed_hours,'attemptedSlots':attempted,'completedYield':len(done)/attempted if attempted else 0,'completedPerHour':rate},'failures':{'parseOrStageErrors':sum(bool(v.get('parseError')) for v in versions),'retryVersions':sum(v['attempt']>0 for v in versions),'finalValidationFailureSlots':sum(bool((r.get('validation') or {}).get('errors')) for r in rows),'missingSourceSlots':sum(r['status']=='NEEDS_SOURCE' for r in rows),'missingAssetSlots':sum(bool((r.get('validation') or {}).get('missingAssets')) for r in rows),'failedSlots':sum(r['status']=='FAILED' for r in rows)},'projection':{'remainingTo50':remaining,'hoursTo50AtObservedRate':remaining/rate if rate else None,'hoursTo50AtSuccessfulMean':remaining*statistics.mean(package_minutes)/60 if package_minutes else None,'additionalValidatedToMinimumTwo':sum(max(0,2-n) for n in counts.values()),'minimumTwoHoursAtObservedRate':sum(max(0,2-n) for n in counts.values())/rate if rate else None,'caveats':['Historical sample includes pilot failures, retries, queue waits and unobserved execution windows.','Successful-runtime projection ignores failed attempts and human approval delay; it is optimistic.','New source copy and a correction to boilerplate-weighted duplicate comparison may change throughput, but that improvement is unmeasured.','Nine recovery compositions have source review packages; actual approval decisions are listed below.','The target and deadline remain unchanged; recovery job versions and asset blockers are recorded below.']},'recoveryProgress':[{'id':r['id'],'status':r['status'],'stage':r['stage'],'sourceValidated':(r.get('validation') or {}).get('criteria',{}).get('sources',False),'missingAssets':(r.get('validation') or {}).get('missingAssets',[]),'versions':[{'stage':v['stage'],'model':v['result']['contract']['model'],'verifiedUnloadAt':v['result']['lifecycle'].get('verifiedUnloadAt'),'lifecycleState':v['result']['lifecycle'].get('state'),'parseError':v.get('parseError')} for v in r['versions']]} for r in rows if r['projectId'] in ['terra-steam-tycoon','angband','find-my-needs'] and r['versions']],'sourceCandidates':[{'id':c['id'],'projectId':c['projectId'],'documents':c['documents'],'proposedConcepts':[v['topic'] for v in c['profile']['approvedContent'] if v['id'].startswith('reviewed-')],'sha256':hashlib.sha256((ROOT/'data/source-recovery/candidates'/f"{c['id']}.json").read_bytes()).hexdigest(),'status':'PENDING_APPROVAL'} for c in candidates],'preservationRecords':[{'id':r['id'],'sha256':hashlib.sha256(json.dumps(r,sort_keys=True,separators=(',',':')).encode()).hexdigest()} for r in done],'service':{'mode':state['mode'],'gateReason':state.get('gateReason'),'error':state.get('error'),'pilotVerified':state['pilotVerified'],'activeJobs':[r['id'] for r in rows if r.get('job')],'missedExecutionWindows':state['sleepWindows']}}
# Candidate status is the actual durable approval decision, never inferred from file presence.
approvals=ROOT/'config/source-approvals.json'
approved_records={a['candidateId']:a for a in json.loads(approvals.read_text())['approvals']} if approvals.exists() else {};approved_ids=set(approved_records)
for c in report['sourceCandidates']:
 decision=ROOT/'data/source-recovery/decisions'/f"{c['id']}.json"
 c['approval']=({k:approved_records[c['id']][k] for k in ['approvedAt','actor','reason']} if c['id'] in approved_records else None)
 c['status']='APPROVED' if c['id'] in approved_ids else json.loads(decision.read_text())['status'] if decision.exists() else 'PENDING_APPROVAL'
OUT=ROOT/'data/campaigns'/CID/'source-recovery'/NOW.strftime('%Y-%m-%dT%H-%M-%S-%fZ')
OUT.mkdir(parents=True,exist_ok=False)
(OUT/'throughput.json').write_text(json.dumps(report,indent=2)+'\n')
for c in candidates:shutil.copyfile(ROOT/'data/source-recovery/candidates'/f"{c['id']}.json",OUT/f"{c['id']}.json")
lines=['# Campaign source recovery','','Campaign: '+CID,'Captured: '+NOW.isoformat(),'Deadline: October 12, 2026, noon America/Chicago','Service: '+state['mode']+'; gate: '+str(state.get('gateReason')),'Error: '+str(state.get('error')),'','## Actual completion','','| Project | Completed validated | Source package | New reviewed compositions |','|---|---:|---|---:|']
for project,count in counts.items():
 c=next(c for c in report['sourceCandidates'] if c['projectId']==project)
 lines.append(f"| {project} | {count}/10 | {c['status']} | {len(c['proposedConcepts'])} |")
lines+=['','## Source approval packages','','All documents have precise excerpts, current byte hashes and modification timestamps in the candidate JSON. CODE_VERIFIED means source inspection only, not a live product test. Audience, CTA, voice and editorial copy require human review.','']
for c in candidates:
 lines+=['### '+c['profile']['name'],c['identity'],'Package: '+c['id'],'Claims/compositions: '+', '.join(v['topic'] for v in c['profile']['approvedContent'] if v['id'].startswith('reviewed-')),'Candidate sources: '+', '.join(d['repository']+'/'+d['path'] for d in c['documents']),'Risks: '+'; '.join(c['risks']),'Assets: '+(json.dumps(c['assets']) if c['assets'] else 'No approved product screenshot or recording identified in bounded discovery.'),'']
lines+=['## Existing source boundaries','','Previously approved: Whodunnit synthetic rewrite pair and writing brand copy; GigWise general recordkeeping copy, date/business-purpose/matching receipt educational guidance. Both existing profiles and source files are unchanged.','','Unsuitable: legacy Angband 4.2.6 material and loose Angband OG prototype do not identify this campaign product; Wand or Steel React/Vite README is a template; GigWise MVP blueprint is not proof of implementation; Find My Needs demonstration requirements are not authoritative law. Concept art is not gameplay. No tax eligibility claims are proposed.','','## Throughput and deadline','','Successful completed-package mean: %.2f minutes (%d samples). Historical completed yield: %.1f%% (%d/%d attempted slots). Effective observed delivery: %.2f validated packages/hour over %.2f hours.'%(statistics.mean(package_minutes),len(package_minutes),100*len(done)/attempted,len(done),attempted,rate,observed_hours),'Qwen: '+json.dumps(latencies['qwen']),'Bonsai: '+json.dumps(latencies['bonsai']),'Failures: '+json.dumps(report['failures']),str(remaining)+' remaining at the observed rate: %.1f hours; optimistic successful-runtime-only estimate: %.1f hours. About %.1f hours remain. Finishing 50 by noon is unlikely on the observed evidence.'%(remaining/rate,remaining*statistics.mean(package_minutes)/60,report['hoursRemaining']),'Minimum two per project initially needed six new validated packages: approximately %.1f hours at the historical effective rate, conditional on machine availability, unchanged sources, review success, and Terra gameplay footage plus a footage-driven composition.'%(6/rate),'','## Exact next actions','','All five initial source packages are now explicitly APPROVED in the dashboard. The source approvals and exact human notes are recorded in throughput.json.','1. Review the recovered drafts and model critiques in the existing campaign dashboard; video proposal approval remains separate.','2. Terra approval requires gameplay shots. Provide and explicitly approve actual Terra gameplay footage with provenance/licensing, and a matching footage-driven storyboard/script before production. Its text-only draft is retained with NEEDS_ASSET.','3. Supply/approve additional distinct compositions for slots beyond the three initially reviewed concepts per recovered project. New additive package IDs preserve previous source/copy approvals.','4. Review Whodunnit and GigWise existing editorial failures separately; their old completed proposals remain frozen. Exhausted revision budgets are not automatically reset.','5. Keep the Mac and existing services available. The same RUNNING campaign uses ordinal passes and existing exclusive model leases; no source, asset, content, render or publish approval is inferred.','','## Verification','','Factory tests: 63 passed. TypeScript checks passed. Real running dashboard smoke tested at desktop and mobile; automation did not approve live sources; the operator explicitly approved all five packages. Isolated fixture approval proves selective resumption and restart persistence. Real approved-source Terra Qwen → Bonsai → Qwen → Bonsai results and unload receipts are recorded in throughput.json; its required gameplay footage remains an asset blocker. Command Center lifecycle was not modified.','Completed validated proposal records are recorded by immutable content hashes in throughput.json; compare to the pre-change preservation capture.','','## Operation','','```sh','npm run cli -- campaign status','npm run cli -- campaign refresh-sources','npm run cli -- campaign export','python3 scripts/report-campaign-throughput.py','```','','If approval committed but campaign refresh failed: review the recorded decision, resolve the reported blocker, then refresh sources. If approval.lock persists after a crash, confirm no approval operation is active and inspect durable state before manual safe recovery; no automatic destructive recovery is attempted.']
(OUT/'SUMMARY.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'reportDirectory':str(OUT),'counts':counts,'modelLatencies':latencies,'packageMeanMinutes':report['packageRuntime']['meanMinutes'],'observation':report['observation'],'failures':report['failures'],'projection':report['projection'],'hoursRemaining':report['hoursRemaining']},indent=2))
